#### Example 4: Rego Policy — Kubernetes Resource Limits (CronJob)

```rego
# policy/k8s/resource-limits.rego
package gainwell.k8s.resource_limits

import future.keywords.if
import future.keywords.in

# Applies to CronJobs running PHI batch workloads
# Soft warning from 2026-04-01; hard denial from 2026-07-01

deny[msg] if {
  input.kind == "CronJob"
  container := input.spec.jobTemplate.spec.template.spec.containers[_]
  not container.resources.limits.cpu
  msg := sprintf(
    "CronJob '%v' container '%v' has no CPU limit. Unbounded CPU can starve cluster neighbors. Add resources.limits.cpu.",
    [input.metadata.name, container.name]
  )
}

deny[msg] if {
  input.kind == "CronJob"
  container := input.spec.jobTemplate.spec.template.spec.containers[_]
  not container.resources.limits.memory
  msg := sprintf(
    "CronJob '%v' container '%v' has no memory limit. Unbounded memory can cause OOMKill across the node. Add resources.limits.memory.",
    [input.metadata.name, container.name]
  )
}

deny[msg] if {
  input.kind == "CronJob"
  container := input.spec.jobTemplate.spec.template.spec.containers[_]
  not container.resources.requests.cpu
  msg := sprintf(
    "CronJob '%v' container '%v' has no CPU request. Kubernetes scheduler requires requests for bin-packing. Add resources.requests.cpu.",
    [input.metadata.name, container.name]
  )
}

